// 1. Parse the JSON response body
var jsonData = pm.response.json();

// 2. Check if the 'access_token' property exists
if (jsonData && jsonData.access_token) {
    // 3. Set the value of 'access_token' to a variable named 'accessToken'
    //    in the currently active Environment.
    pm.environment.set("accessToken", jsonData.access_token);
    
    // Optional: Log a success message to the Postman Console
    console.log("Access Token set: " + jsonData.access_token);
} else {
    // Optional: Log an error if the token wasn't found
    console.error("Access token not found in response.");
}

// Check if the 'refresh_token' property exists
if (jsonData && jsonData.refresh_token) {
    pm.environment.set("refreshToken", jsonData.refresh_token);
    console.log("Refresh Token set: " + jsonData.refresh_token);
} else {
    console.error("Refresh token not found in response.");
}

